let lastSavedOwned=new Set(state.owned);function recordOwnedSource(id,source){if(!id||!source)return;state.ownedSources=state.ownedSources&&typeof state.ownedSources==='object'?state.ownedSources:{};const list=Array.isArray(state.ownedSources[id])?state.ownedSources[id]:[];if(!list.includes(source))list.push(source);state.ownedSources[id]=list}function save(){try{state.ownedAt=state.ownedAt&&typeof state.ownedAt==='object'?state.ownedAt:{};state.ownedSource=state.ownedSource&&typeof state.ownedSource==='object'?state.ownedSource:{};state.ownedSources=state.ownedSources&&typeof state.ownedSources==='object'?state.ownedSources:{};for(const id of state.owned){if(!lastSavedOwned.has(id)&&!state.ownedAt[id])state.ownedAt[id]=Date.now();if(!state.ownedSource[id])state.ownedSource[id]='collection';recordOwnedSource(id,state.ownedSource[id])}const serialized=JSON.stringify(state);localStorage.setItem(KEY,serialized);if(localStorage.getItem(KEY)!==serialized)return false;lastSavedOwned=new Set(state.owned);return true}catch(e){return false}}function restoreRewardState(snapshot){try{state=JSON.parse(snapshot);lastSavedOwned=new Set(Array.isArray(state.owned)?state.owned:[]);render();showToast('Не вдалося зберегти нагороду. Перевір вільне місце на пристрої та спробуй ще раз.')}catch(e){showToast('Не вдалося зберегти нагороду. Спробуй ще раз.')}}
