function renderDailyMissions(){const el=$('#dailyMissions');if(!el)return;ensureDailyMissions();const doneCount=dailyMissions.filter(m=>state.dailyMissionClaims.includes(m.id)).length;const progress=$('#dailyMissionProgress');if(progress)progress.textContent=doneCount+' / '+dailyMissions.length+' ЗАБРАНО';el.innerHTML=dailyMissions.map(m=>{const ready=m.test(),claimed=state.dailyMissionClaims.includes(m.id);return '<article class="daily-mission-row '+(claimed?'done':'')+'"><div class="mission-check">'+(claimed?'✓':ready?'!':'◇')+'</div><div class="mission-copy"><b>'+m.title+'</b><small>'+m.desc+'</small><small class="daily-mission-reward">◈ +'+m.reward+' монет · ⚡ +'+m.xp+' XP</small></div><button type="button" class="daily-mission-claim" data-daily-claim="'+m.id+'" '+(!ready||claimed?'disabled':'')+'>'+(claimed?'ЗАБРАНО ✓':ready?'ЗАБРАТИ':'У ПРОЦЕСІ')+'</button></article>'}).join('')}
