function renderExtraArcadeGames(){
 const grid=document.querySelector('#tab-games .games-grid');if(!grid)return;
 const existing=new Set([...grid.querySelectorAll('[data-game]')].map(b=>b.dataset.game));
 extraArcadeGames.slice(0,60).forEach((g,i)=>{if(existing.has('arcade-'+g.id))return;const card=document.createElement('article');card.className='game-tile arcade-tile';card.innerHTML='<div class="tile-visual visual-aim"><span>'+g.icon+'</span><b>'+(40+i)+' / '+g.tag+'</b></div><div class="tile-content"><div class="tile-meta">'+(40+i)+' / '+g.tag+'</div><h3>'+g.name+'</h3><p>'+g.desc+'</p><div class="tile-reward">◈ +'+(10+(i%4)*5)+' монет <span>✧ +'+(15+(i%5)*5)+' очок</span></div><button class="btn btn-yellow full" data-game="arcade-'+g.id+'">ЗАПУСТИТИ</button></div>';grid.appendChild(card)});
 const count=document.querySelector('#gameNavCount');if(count)count.textContent='100';
}
