 const sets=questionSets[id]||[[g.name,['Обрати тактику','Поспішити','Ігнорувати ситуацію'],0,'Чудово!'],['Наступний крок?',['Перевірити укриття','Бігти відкрито','Зупинитися'],0,'Тактика працює.'],['Фінальне рішення?',['Допомогти загону','Розбігтися','Забути про зону'],0,'Раунд завершено.']];
 const draw=()=>{if(done)return;if(round>=sets.length){finish();return}const q=sets[round];box.innerHTML='<div class="arcade-progress">РАУНД '+(round+1)+' / '+sets.length+' · ОЧКИ '+score+'</div><h3>'+q[0]+'</h3>';const opts=q[1].slice();opts.forEach((label,i)=>{const b=btn(label,()=>{if(done)return;const correct=i===q[2];if(correct)score++;message.textContent=(correct?'✓ ':'✕ ')+q[3];round++;setTimeout(draw,500)},'arcade-option');});};
 if(id==='lootbox'){box.innerHTML='<h3>ОБЕРИ ОДИН ІЗ ТРЬОХ ЯЩИКІВ</h3>';['▣ ЯЩИК A','▣ ЯЩИК B','▣ ЯЩИК C'].forEach((label,i)=>btn(label,()=>{if(done)return;const prize=Math.random();score=prize>.78?3:prize>.45?2:1;round=3;box.innerHTML='<h3>'+(score===3?'✨ РІДКІСНИЙ ДРОП!':score===2?'◈ ХОРОШИЙ ЛУТ':'🎒 БАЗОВИЙ ЛУТ')+'</h3><p>Ящик '+label.slice(-1)+': '+score+' очки луту.</p>';btn('ЗАВЕРШИТИ РЕЙД',finish,'arcade-option')}));return}
 if(id==='reload'||id==='grenade'){box.innerHTML='<h3>ЗУПИНИ ІНДИКАТОР У ЗЕЛЕНІЙ ЗОНІ</h3><div class="timing-track"><i id="timingMarker"></i><b></b></div>';const track=box.querySelector('.timing-track'),marker=box.querySelector('#timingMarker');let pos=0,dir=1;const interval=setInterval(()=>{pos+=dir*3.2;if(pos>96||pos<0)dir*=-1;marker.style.left=pos+'%'},35);cleanups.push(()=>clearInterval(interval));btn('ЗУПИНИ!',()=>{clearInterval(interval);score=Math.abs(pos-50)<17?3:Math.abs(pos-50)<32?2:1;round=3;box.innerHTML='<h3>'+ (score===3?'ІДЕАЛЬНИЙ ТАЙМІНГ!':score===2?'НЕПОГАНО!':'ЩЕ ТРЕНУЙСЯ!')+'</h3><p>Точність: '+score+'/3</p>';btn('ЗАВЕРШИТИ',finish,'arcade-option')},'arcade-option');return}
 draw();
