$('#checkInstall')?.addEventListener('click',async()=>{
 const out=$('#installCheckResult');out.textContent='Перевіряю manifest і service worker…';
 const standalone=window.matchMedia?.('(display-mode: standalone)').matches||window.navigator.standalone===true;
 const secure=window.isSecureContext;
 let manifestOk=false,swOk=false,manifestDisplay='невідомо',swState='не підтримується';
 try{const link=document.querySelector('link[rel="manifest"]');if(link){const r=await fetch(link.href,{cache:'no-store'});if(r.ok){const m=await r.json();manifestOk=!!(m.name&&m.start_url&&Array.isArray(m.icons)&&m.icons.length);manifestDisplay=m.display||'не задано'}}}catch{}
 try{if('serviceWorker' in navigator){const reg=await navigator.serviceWorker.getRegistration('./');swOk=!!(reg&&(reg.active||reg.waiting||reg.installing));swState=reg?.active?'активний':reg?.waiting?'очікує активації':reg?.installing?'встановлюється':'не зареєстрований'}}catch{}
 const installPrompt=!!window.pwaPrompt||('onbeforeinstallprompt' in window);
 out.innerHTML='<b>'+(standalone?'ЗАПУЩЕНО ЯК ДОДАТОК':'ВІДКРИТО В БРАУЗЕРІ')+'</b><span>HTTPS: '+(secure?'так':'ні')+'</span><span>Manifest: '+(manifestOk?'OK':'не підтверджено')+' · display: '+manifestDisplay+'</span><span>Service worker: '+(swOk?'OK':'не підтверджено')+' ('+swState+')</span><span>Подія встановлення: '+(installPrompt?'підтримується браузером':'може не підтримуватися в цьому браузері')+'</span><small>'+(standalone?'Застосунок уже відкритий у встановленому режимі на цьому пристрої.':'Якщо HTTPS, manifest і service worker справні, відкрий меню браузера та вибери «Установити додаток». Цей тест не може підтвердити встановлення на іншому пристрої.')+'</small>';
});

function assistantReply(raw){
 const q=raw.toLowerCase();
 if(/челендж|виклик|challenge|рандом/.test(q)){const challenges=['Наступний матч: тільки лут із першого будинку. Так, навіть якщо там лише сковорідка 😅','Режим тихого ніндзя: не стріляй першим, доки не зміниш позицію.','Лут-детектив: знайди аптечку й приціл до першої серйозної перестрілки.','Командний режим: кожні 2 хвилини перевіряй, чи загін ще з тобою.','Хардкор: після кожного нокауту міняй позицію.','Metro challenge: винеси лише те спорядження, яке готовий ризикнути втратити.','Безпечний топ-10: обирай укриття й ротацію раніше за перестрілку.'];return '🎯 Челендж від напарника KH: '+challenges[Math.floor(Math.random()*challenges.length)]+' Напиши «ще челендж», якщо хочеш новий.'}
 if(/інвентар|екіп|скін|шолом|рюкзак|зброю|магазин бійц/.test(q))return '🪖 Інвентар бійця відкривається з блоку твого персонажа. Предмети мають рідкість і слоти: скін, зброя, шолом, броня та рюкзак. Купівлі зберігаються на цьому пристрої.';
 if(/загін|squad|напарник|склад/.test(q))return '👥 Зайди в «Тактичний штаб» → «Склад загону». Запиши штурмовика, снайпера, підтримку й розвідника, а потім збережи склад.';
 if(/metro|метро/.test(q))return '🚇 Metro доступний у хабі як тематичне браузерне випробування. Воно не підключається до офіційного клієнта PUBG і не переносить лут у гру.';
 if(/classic|класик|4\.6|версі/.test(q))return '🎮 У хабі є класичні й тематичні ігрові випробування. Це не відновлення старого офіційного клієнта PUBG 4.6.';
 if(/пабг.*пк|пк.*пабг|steam|комп.?ютер/.test(q))return '💻 Для PUBG на ПК натисни окрему кнопку «PUBG: BATTLEGROUNDS» на головній сторінці. Для самого хабу можна скористатися «Встановити на ПК».';
 if(/pubg mobile|мобільн|андроїд|play market/.test(q))return '📱 На головній сторінці є окрема кнопка PUBG MOBILE, яка відкриває Google Play.';
 if(/музик|spotify|youtube/.test(q))return '♫ Відкрий «Музика», вибери добірку та запускай плеєр. Відтворення залежить від YouTube і дозволів браузера.';
 if(/tiktok|тікток|відео/.test(q))return '♪ У «Мої відео TikTok» є окремі профілі @tiktok.comkhkozak4 та @baggy8364. Відкрий профіль; вбудована стрічка залежить від TikTok.';
 if(/сьогод|щоденн|daily|місії|місія/.test(q))return '📋 План на сьогодні: забери щоденний дроп на головній, виконай завдання у вкладці «Місії», зіграй кілька мініігор і перевір нагороди Royale Pass.';
 if(/рів|level|xp|battle pass|пас/.test(q))return '⚡ План прокачки: забери дроп, виконай щоденні місії та грай у мініігри. У Royale Pass забирай доступні нагороди окремими кнопками.';
 if(/монет|coin|зароб|баланс/.test(q))return '💰 Монети заробляються за мініігри, щоденний дроп і місії. Прогрес зберігається локально в цьому браузері.';
 if(/мінігр|грат|ігри|game/.test(q))return '🎮 У хабі є реакція, Aim Trainer, PUBG Quiz, пам’ять, лут-випробування, класичні/Metro-теми та велика аркада. Відкрий «Ігри та режими» або «3D Арена».';
 if(/telegram|телеграм|бот/.test(q))return '📡 У вкладці Telegram знайдеш контакти, TikTok-акаунти та канал. Посилання відкривають відповідні застосунки або сайти.';
 if(/профіл|статист|нік|ранг/.test(q))return '🪪 У «Моєму профілі» є статистика, прогрес, інвентар і нагороди. Дані зберігаються на цьому пристрої.';
 if(/допом|привіт|hello|hi|хто ти/.test(q))return 'Йо, боєць! Я KH Squadmate — помічник Battle Hub 😎 Підкажу щодо прогресу, інвентарю, загону, PUBG PC/Mobile, Metro, музики, TikTok і щоденних місій.';
 return 'Так, командире 😎 Спробуй запитати: «дай челендж», «як заробити монети?», «як екіпірувати скін?», «що робити сьогодні?» або «де PUBG для ПК?».';
}
